import json, inspect
from pathlib import Path
# Complete demonstration archive.
demo3={"input":[[7,7,7,0,7,7,7,0,7,7,7,7,7,7] for _ in range(11)]+[[7,7,0,0,0,7,0,0,0,7,7,7,7,7],[7,9,0,7,0,7,0,7,0,9,7,7,7,7],[7,9,0,7,0,9,0,7,0,9,7,7,9,7]],"output":[[7,7,0,0,0,7,0,0,0,7,7,7,7,7],[7,7,0,7,0,7,0,7,0,7,7,7,7,7],[7,7,0,7,0,7,0,7,0,7,7,7,7,7]]+[[7]*14 for _ in range(9)]+[[7,9,7,7,7,7,7,7,7,9,7,7,7,7],[7,9,7,7,7,9,7,7,7,9,7,7,9,7]]}
demo4={"input":inp2 and [[7]*7+[0]*3,[0]*8+[7,9],[7]*7+[0]*3,[7]*10,[7]*8+[9,9],[7]*7+[0]*3,[0]*8+[7,7],[7]*7+[0]*3,[7]*9+[9],[7]*10],"output":[[0]*3+[7]*7,[0,7,9]+[7]*7,[0]*3+[7]*7,[7]*10,[7]*8+[9,9],[0]*3+[7]*7,[0]+[7]*9,[0]*3+[7]*7,[7]*9+[9],[7]*10]}
pairs=[demo,{"input":inp2,"output":out2},demo3,demo4]
program='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    p9 = [(r,c) for r in range(h) for c in range(w) if g[r][c] == 9]
    if max(c for r,c in p9) >= w-2:
        axis, target = 1, 0
    elif min(c for r,c in p9) <= 1:
        axis, target = 1, 1
    elif max(r for r,c in p9) >= h-2:
        axis, target = 0, 0
    else:
        axis, target = 0, 1
    out = [[7]*w for _ in range(h)]
    for r,c in p9:
        out[r][c] = 9
    if axis == 1:
        for r in range(h):
            c = 0
            touched = False
            while c < w:
                if g[r][c] != 0:
                    c += 1
                    continue
                s = c
                while c < w and g[r][c] == 0:
                    c += 1
                n = c-s
                if target == 0:
                    if s == 0:
                        n = 1
                        touched = True
                    start = 0
                else:
                    if c == w:
                        n = 1
                        touched = True
                    start = w-n
                for k in range(n):
                    out[r][start+k] = 0
            if touched:
                colors = [g[r][c] for c in range(w) if g[r][c] != 0]
                for c in range(w):
                    out[r][c] = 7
                if target == 0:
                    for k in range(n):
                        out[r][k] = 0
                    for k,color in enumerate(colors):
                        out[r][n+k] = color
                else:
                    for k,color in enumerate(colors):
                        out[r][k] = color
                    for k in range(n):
                        out[r][w-n+k] = 0
    else:
        for c in range(w):
            r = 0
            while r < h:
                if g[r][c] != 0:
                    r += 1
                    continue
                s = r
                while r < h and g[r][c] == 0:
                    r += 1
                n = r-s
                if target == 0:
                    if s == 0:
                        n = 1
                    start = 0
                else:
                    if r == h:
                        n = 1
                    start = h-n
                for k in range(n):
                    out[start+k][c] = 0
    return out
'''
ns={};exec(program,ns)
for i,p in enumerate(pairs):
    assert ns['transform'](p['input'])==p['output'],i
(pdir/f'{tid}.json').write_text(json.dumps(pairs,indent=2))
(pdir/f'{tid}.py').write_text(program)
